import { experiment } from '@caemble/core'
import { Tower } from './geometry'
import { Steel } from './material'
export default experiment({
  lengthUnit: 'm',
  varsSchema: {},
  geometry: () => <Tower id="body" materials={{ body: Steel() }} />,
  geometryGroup: { body: ['body'] },
  surfaceGroup: {
    fixed: ['body.outer/surface/0'],
    loaded: ['body.outer/surface/2'],
  },
  recordedData: {
    displacement: { task: 'detail', output: 'displacement' },
    reaction: { task: 'detail', output: 'reaction' },
    stress: { task: 'detail', output: 'stress' },
    stressField: { task: 'detail', output: 'stressField' },
  },
})

files.material.tsx:
import { Material } from '@caemble/core'
// E: 늘어나기 어려운 정도(Pa), nu: 옆으로 수축하는 비율, density: 단위 체적의 질량.
export const Steel = () => new Material('Steel', {
  color: '#7589a0',
  models: { solid: { model: 'mechanics.isotropic-elastic@1', parameters: {
    E: { dtype: 'float64', value: 210e9, unit: 'Pa' },
    nu: { dtype: 'float64', value: 0.3, unit: '1' },
    density: { dtype: 'float64', value: 7850, unit: 'kg.m-3' },
  } } },
})

